# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(1,'Dans D&D 5e, lequel de ces dragons n’est pas un dragon chromatique ?','Dragon d’or',['Dragon rouge','Dragon bleu','Dragon noir'],'Le dragon d’or est un dragon métallique (bon). Les cinq chromatiques sont le rouge, le bleu, le vert, le noir et le blanc.',MM+', chapitre « Dragons »')
I(2,'Dans D&D 5e, lequel de ces dragons ne crache pas de feu ?','Dragon de bronze',['Dragon rouge','Dragon d’or','Dragon d’airain'],'Le dragon de bronze crache de la foudre. Les dragons rouge, d’or et d’airain ont tous un souffle de feu.',MM+', entrées des dragons de bronze, rouge, d’or et d’airain')
I(3,'Dans D&D 5e, laquelle de ces créatures n’est pas de type « dragon » ?','Hydre',['Wyverne','Pseudo-dragon','Tortue-dragon'],'L’hydre est une monstruosité. La wyverne, le pseudo-dragon et la tortue-dragon sont bien de type dragon.',MM+', entrées « Hydre », « Wyverne », « Pseudo-dragon », « Tortue-dragon »')
T(2,'Dans D&D 5e, le dragon d’argent possède deux souffles : un cône de froid et un souffle de gaz ____.','paralysant',['ralentissant','répulsif','endormant'],'Le gaz paralysant est celui du dragon d’argent. Le ralentissement est celui du cuivre, la répulsion celle du bronze, le sommeil celui de l’airain.',MM+', entrée « Dragon d’argent »')
T(2,'Dans D&D 5e, la ____ est un cousin du dragon à deux pattes, dont la queue est armée d’un dard venimeux.','wyverne',['hydre','chimère','manticore'],'La wyverne est une créature de type dragon, à deux pattes et deux ailes, dont le dard de queue est empoisonné.',MM+', entrée « Wyverne »')
T(1,'Dans D&D 5e, les quatre stades de vie d’un dragon sont : dragonnet, jeune, adulte, puis ____.','ancien',['vénérable','suprême','légendaire'],'Les dragons passent par les stades de dragonnet, jeune dragon, dragon adulte et dragon ancien.',MM+', chapitre « Dragons »')
M(1,'Dans D&D 5e, lesquels de ces dragons sont chromatiques ? (plusieurs bonnes réponses)',['Rouge','Bleu','Blanc'],['Argent','Bronze'],'Rouge, bleu et blanc sont chromatiques, comme le noir et le vert. L’argent et le bronze sont des dragons métalliques.',MM+', chapitre « Dragons »')
M(2,'Dans D&D 5e, quels dragons métalliques ont un souffle de feu ? (plusieurs bonnes réponses)',['Dragon d’or','Dragon d’airain'],['Dragon de cuivre','Dragon de bronze','Dragon d’argent'],'Or et airain crachent du feu. Le cuivre crache de l’acide, le bronze de la foudre, l’argent du froid.',MM+', entrées des dragons métalliques')
M(3,'Dans D&D 5e, quels dragons chromatiques ont un souffle en cône (et non en ligne) ? (plusieurs bonnes réponses)',['Rouge','Vert','Blanc'],['Bleu','Noir'],'Les dragons rouge, vert et blanc soufflent en cône ; les dragons bleu (foudre) et noir (acide) soufflent en ligne.',MM+', entrées des dragons chromatiques')
O(1,'Remets dans l’ordre les stades de vie d’un dragon, du plus jeune au plus ancien.',['Dragonnet','Jeune dragon','Dragon adulte','Dragon ancien'],'Le dragon grandit de dragonnet à ancien, et sa puissance (FP) augmente à chaque stade.',MM+', chapitre « Dragons »')
O(2,'Classe ces créatures de la plus petite à la plus grande catégorie de taille.',['Pseudo-dragon','Dragonnet rouge','Jeune dragon rouge','Dragon rouge adulte','Dragon rouge ancien'],'Tailles : minuscule (pseudo-dragon), moyenne (dragonnet), grande (jeune), très grande (adulte), gigantesque (ancien).',MM+', entrées « Pseudo-dragon » et « Dragon rouge »')
A(1,'Associe chaque dragon chromatique à son type de souffle.',[('Dragon rouge','Feu'),('Dragon bleu','Foudre'),('Dragon noir','Acide'),('Dragon blanc','Froid')],'Rouge = feu, bleu = foudre, noir = acide, blanc = froid (et vert = poison).',MM+', entrées des dragons chromatiques')
A(2,'Associe chaque dragon métallique à son souffle « spécial » (non destructeur).',[('Dragon d’argent','Paralysie'),('Dragon d’or','Affaiblissement'),('Dragon d’airain','Sommeil'),('Dragon de cuivre','Ralentissement')],'Chaque dragon métallique a un second souffle qui handicape plutôt qu’il ne blesse.',MM+', entrées des dragons métalliques')
A(2,'Associe chaque dragon chromatique à son milieu de prédilection.',[('Dragon blanc','Régions glaciales'),('Dragon noir','Marais'),('Dragon vert','Forêts'),('Dragon bleu','Déserts')],'Blanc : froid polaire ; noir : marais ; vert : forêts ; bleu : déserts ; rouge : montagnes et volcans.',MM+', entrées des dragons chromatiques')
W(1,['Je suis un dragon chromatique.','Mon souffle est un cône de feu.','Orgueilleux et cupide, je vis dans les montagnes et les volcans.'],'Dragon rouge',['Dragon d’or','Dragon bleu','Dragon blanc'],'Le dragon rouge est le plus puissant et le plus orgueilleux des chromatiques.',MM+', entrée « Dragon rouge »')
W(2,['Je suis un dragon, mais je mesure à peine trente centimètres.','Ma queue se termine par un dard venimeux.','Je communique par télépathie et je sers volontiers de familier à un magicien.'],'Pseudo-dragon',['Wyverne','Dragon-fée','Dragonnet rouge'],'Le pseudo-dragon est un minuscule dragon télépathe, doté d’un dard venimeux et d’une résistance à la magie.',MM+', entrée « Pseudo-dragon »')
W(3,['Je suis de type dragon, mais j’ai la forme d’une gigantesque tortue.','Je vis dans les profondeurs océaniques et j’adore l’or.','Mon souffle est un cône de vapeur brûlante.'],'Tortue-dragon',['Hydre','Kraken','Wyverne'],'La tortue-dragon fait chavirer les navires et amasse de l’or ; son souffle est de la vapeur.',MM+', entrée « Tortue-dragon »')
save('dragons-dnd','dra')
